@Test
public void computeIfAbsent() {
    ConcurrentLinkedHashMap m = new ConcurrentLinkedHashMap.Builder<>().maximumWeightedCapacity(3).build();
    assertEquals(1, m.computeIfAbsent("a", k -> 1));
    assertEquals(1, m.computeIfAbsent("a", k -> 2));
    assertEquals(1, m.get("a"));
    assertEquals(3, m.computeIfAbsent("b", k -> 3));
    assertEquals(4, m.computeIfAbsent("c", k -> 4));
    assertEquals(5, m.computeIfAbsent("d", k -> 5));
    assertEquals(5, m.computeIfAbsent("d", k -> 6));
    assertArrayEquals(new String[] { "b", "c", "d" }, m.keySet().toArray(new String[0]));
    assertArrayEquals(new Integer[] { 3, 4, 5 }, m.values().toArray(new Integer[0]));
}

@Test
public void computeIfAbsentConcurrently() throws InterruptedException {
    final ConcurrentLinkedHashMap m = new ConcurrentLinkedHashMap.Builder<>().maximumWeightedCapacity(3).build();
    final int threadNum = 20;
    final CountDownLatch countDownLatch = new CountDownLatch(1);
    final CountDownLatch countDownLatch2 = new CountDownLatch(threadNum);
    for (int i = 0; i < threadNum; i++) {
        final int num = i;
        new Thread(() -> {
            try {
                countDownLatch.await();
                m.computeIfAbsent(num % 3, k -> num);
            } catch (InterruptedException e) {
                e.printStackTrace();
            } finally {
                countDownLatch2.countDown();
            }
        }).start();
    }
    countDownLatch.countDown();
    countDownLatch2.await();
    m.computeIfAbsent(0, k -> 100);
    assertArrayEquals(new Integer[] { 0, 1, 2 }, new TreeSet(m.keySet()).toArray(new Integer[0]));
    assertNotEquals(100, m.get(0));
    assertEquals(0, (Integer) m.get(0) % 3);
    assertEquals(1, (Integer) m.get(1) % 3);
    assertEquals(2, (Integer) m.get(2) % 3);
}

@Test
public void inverse() {
    Map<String, Integer> map = Maps.of("a", 1, "b", 2, "c", 3);
    Map<Integer, String> inversedMap = Maps.inverse(map);
    Assert.assertEquals(map.size(), inversedMap.size());
    for (Map.Entry<Integer, String> entry : inversedMap.entrySet()) {
        Assert.assertEquals(map.get(entry.getValue()), entry.getKey());
    }
    try {
        Maps.inverse(Maps.of("a", 1, "b", 2, "c", 2));
    } catch (IllegalArgumentException e) {
        Assert.assertTrue(e.getMessage().contains("duplicated key found: 2"));
    }
    Map<Integer, String> inversedMap2 = Maps.inverse(Maps.of("a", 1, "b", 2, "c", 2), true);
    Assert.assertEquals(2, inversedMap2.size());
    Assert.assertEquals("a", inversedMap2.get(1));
    Assert.assertEquals("c", inversedMap2.get(2));
}

